def decode("") do
  {:ok, nil}
end
def decode(binary) do
  term = Plug.Crypto.non_executable_binary_to_term(binary)
  {:ok, term}
rescue
  ArgumentError -> {:error, "bad binary_to_term"}
end

def strictest(candidates) do
  candidates
  |> Enum.map(fn {tag, dur} ->
    case is_binary(dur) && duration_to_seconds(dur) do
      {:ok, 0} -> {tag, "0d", 0}
      {:ok, seconds} -> {tag, dur, seconds}
      _ -> {tag, "0d", 0}
    end
  end)
  |> Enum.max_by(&elem(&1, 2))
  |> then(fn {tag, dur, _} -> {tag, dur} end)
end

